use wafer_protocol::nbt::Nbt;

use crate::core::data_registries;
use crate::network::chat::component_serialization;
use crate::util::codec::DecodeResult;
use crate::world::item::component::json_to_nbt;
use crate::world::item::enchantment::enchantment_effect_components::EnchantmentEffectComponents;
use crate::world::item::enchantment::level_based_value::LevelBasedValue;
use crate::world::item::trading::villager_trade::VillagerTrade;
use crate::world::level::storage::loot::functions::loot_item_function::LootItemFunction;
use crate::world::level::storage::loot::providers::number::floats::ContextFloatProvider;
use crate::world::level::storage::loot::providers::number::ints::ContextIntProvider;

fn split<T>(result: DecodeResult<T>) -> (Option<String>, bool) {
    let partial = result.error.is_some() && result.value.is_some();
    (result.error, partial)
}

fn component(tag: &Nbt) -> (Option<String>, bool) {
    let error = component_serialization::decode(tag).err();
    let text = crate::world::item::component::text::decode(tag).err();
    let error = if text == error { error } else { Some(format!("text.rs differs: {text:?} vs {error:?}")) };
    let partial = error.is_some() && component_serialization::decode_or_partial(tag).is_some();
    (error, partial)
}

fn decode(kind: &str, json: &str) -> (Option<String>, bool) {
    let tag = json_to_nbt(&serde_json::from_str(json).unwrap());
    crate::nbt::with_json_source(|| match kind {
        "component" => component(&tag),
        "lbv" => split(LevelBasedValue::decode_partial(&tag)),
        "ctxint" => data_registries::with_loading(|| split(ContextIntProvider::decode_partial(&tag))),
        "ctxfloat" => data_registries::with_loading(|| split(ContextFloatProvider::decode_partial(&tag))),
        "typed" => split(LootItemFunction::decode_typed(&tag)),
        "effects" => (EnchantmentEffectComponents::decode(&tag).err(), false),
        "trade" => data_registries::with_loading(|| (VillagerTrade::decode(&tag).err(), false)),
        _ => unreachable!("{kind}"),
    })
}

